interface.signature:
SELECT document_id, entity, metric, value, unit, period, fiscal_year, page_number, table_caption
FROM financial_tables
WHERE document_id = 'document_filename.pdf';

await search_documents(
    query: str,
    top_k: int = 5,
    filters: dict[str, str] | None = None  # e.g., {'source_document': 'Q3_Report.pdf'}
) -> list[QueryResult]
